import React from 'react';
import styled from 'styled-components';

const ContactSection = styled.section`
  max-width: 500px;
  margin: 0 auto;
  padding: 6rem 1.5rem 3rem 1.5rem;
  color: #fff;
  text-align: center;
`;

const Heading = styled.h2`
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 2rem;
  color: #fff;
`;

const Email = styled.a`
  display: inline-block;
  color: #fff;
  font-size: 1.15rem;
  font-weight: 600;
  margin-bottom: 2rem;
  text-decoration: underline;
  opacity: 0.85;
  transition: opacity 0.18s;
  &:hover, &:focus {
    opacity: 1;
  }
`;

const Socials = styled.div`
  display: flex;
  justify-content: center;
  gap: 2rem;
  margin-top: 1.5rem;
`;

const IconLink = styled.a`
  color: #fff;
  opacity: 0.7;
  font-size: 2rem;
  transition: opacity 0.18s;
  &:hover, &:focus {
    opacity: 1;
  }
`;

// Minimal SVG icons (monochrome)
const icons = {
  github: (
    <svg width="28" height="28" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.58 2 12.26c0 4.5 2.87 8.32 6.84 9.67.5.09.68-.22.68-.48 0-.24-.01-.87-.01-1.7-2.78.62-3.37-1.36-3.37-1.36-.45-1.18-1.1-1.5-1.1-1.5-.9-.64.07-.63.07-.63 1 .07 1.53 1.05 1.53 1.05.89 1.56 2.34 1.11 2.91.85.09-.66.35-1.11.63-1.37-2.22-.26-4.56-1.14-4.56-5.07 0-1.12.38-2.03 1-2.75-.1-.26-.44-1.3.1-2.7 0 0 .83-.27 2.75 1.02A9.3 9.3 0 0 1 12 6.84c.84.004 1.68.11 2.47.32 1.92-1.29 2.75-1.02 2.75-1.02.54 1.4.2 2.44.1 2.7.62.72 1 1.63 1 2.75 0 3.94-2.34 4.8-4.57 5.06.36.32.68.94.68 1.9 0 1.37-.01 2.47-.01 2.8 0 .27.18.58.69.48A10.01 10.01 0 0 0 22 12.26C22 6.58 17.52 2 12 2Z"/></svg>
  ),
  linkedin: (
    <svg width="28" height="28" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M16 8a6 6 0 0 1 6 6v5h-4v-5a2 2 0 0 0-4 0v5h-4v-9h4v1.5a4 4 0 0 1 3-1.5Z"/><rect width="4" height="9" x="2" y="9" rx="2"/></svg>
  ),
  mail: (
    <svg width="28" height="28" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><rect width="20" height="16" x="2" y="4" rx="2"/><path d="m22 6-8.97 6.48a2 2 0 0 1-2.06 0L2 6"/></svg>
  )
};

const Contact = () => (
  <ContactSection id="contact">
    <Heading>Contact</Heading>
    <Email href="mailto:valdrin@email.com">valdrin@email.com</Email>
    <Socials>
      <IconLink href="https://github.com/valdrinshala" target="_blank" rel="noopener noreferrer" aria-label="GitHub">
        {icons.github}
      </IconLink>
      <IconLink href="https://linkedin.com/in/valdrinshala" target="_blank" rel="noopener noreferrer" aria-label="LinkedIn">
        {icons.linkedin}
      </IconLink>
      <IconLink href="mailto:valdrin@email.com" aria-label="Email">
        {icons.mail}
      </IconLink>
    </Socials>
  </ContactSection>
);

export default Contact;
